// Port of mozc/src/mac/KeyCodeMap.{h,mm} (3.35.6354).
//
// The key maps (init_kanamap.h, init_specialkeymap.h, init_specialcharmap.h generated by
// mac/generate_mapping.py) are generated into KeyCodeMapTables.swift by Tools/generate_mac_keymaps.py.
// The NSEvent is abstracted as `KeyEventData` so that the logic is testable without a window server;
// `KeyEventData(NSEvent)` copies exactly the properties KeyCodeMap.mm reads.

import AppKit
import Carbon
import GenmaiClient
import GenmaiProtocol

public enum InputMode: Sendable {
  case ascii
  case kana
}

private let kYenMark: unichar = 0xA5

/// The properties of an NSEvent that KeyCodeMap / GenmaiImkInputController use.
public struct KeyEventData: Sendable, Equatable {
  public enum EventType: Sendable, Equatable {
    case keyDown
    case flagsChanged
    case other
  }

  public var type: EventType
  public var characters: String
  public var charactersIgnoringModifiers: String
  public var modifierFlags: NSEvent.ModifierFlags
  public var keyCode: UInt16

  public init(
    type: EventType, characters: String, charactersIgnoringModifiers: String,
    modifierFlags: NSEvent.ModifierFlags, keyCode: UInt16
  ) {
    self.type = type
    self.characters = characters
    self.charactersIgnoringModifiers = charactersIgnoringModifiers
    self.modifierFlags = modifierFlags
    self.keyCode = keyCode
  }

  public init(_ event: NSEvent) {
    switch event.type {
    case .keyDown: type = .keyDown
    case .flagsChanged: type = .flagsChanged
    default: type = .other
    }
    // -characters / -charactersIgnoringModifiers raise for non-key events.
    if type == .keyDown {
      characters = event.characters ?? ""
      charactersIgnoringModifiers = event.charactersIgnoringModifiers ?? ""
    } else {
      characters = ""
      charactersIgnoringModifiers = ""
    }
    modifierFlags = event.modifierFlags
    keyCode = type == .other ? 0 : event.keyCode
  }
}

extension NSEvent.ModifierFlags: @retroactive @unchecked Sendable {}

@MainActor
public final class KeyCodeMap {
  /// stores the current modifiers
  private var modifierFlags: NSEvent.ModifierFlags = []
  public var inputMode: InputMode = .ascii

  public init() {}

  /// Extract Mac modifier flag bits from `flags` and set them into `keyEvent`.
  private func addModifierFlags(_ flags: NSEvent.ModifierFlags, _ keyEvent: inout KeyEvent) {
    if flags.contains(.shift) {
      keyEvent.modifierKeys.append(.shift)
    }
    if flags.contains(.control) {
      keyEvent.modifierKeys.append(.ctrl)
    }
    if flags.contains(.option) {
      keyEvent.modifierKeys.append(.alt)
    }
  }

  /// Extract key event information from `event` of NSEventTypeFlagsChanged.
  /// Returns true only if the flag change should create an Mozc key events.
  private func handleModifierFlagsChange(_ event: KeyEventData, _ keyEvent: inout KeyEvent) -> Bool {
    // Clear unused modifier flag bits.
    let newFlags = event.modifierFlags.intersection([.shift, .control, .option])
    if !modifierFlags.isSuperset(of: newFlags) {
      // New modifier key is pressed: overwrite |modifierFlags_|.
      // Consider the case as follows:
      // 1. shift and control is pressed
      // 2. only control is released
      // 3. alt is newly pressed
      // At that time, modifierFlags_ should be shift+alt.
      modifierFlags = newFlags
    }
    // If new modifier key is not pressed (i.e. some keys are released),
    // we do not update |modifierFlags_| at that time.  |modifierFlags_|
    // will become 0 when all modifier keys are released.

    if !newFlags.isEmpty {
      // The user is still pressing some modifier keys.
      return false
    }
    if newFlags.isEmpty && modifierFlags.isEmpty {
      // The user released modifier keys but modifierFlags_ are already cleared.
      // Ex: Shift -> a (send Shift-a) -> release a -> release Shift (here)
      return false
    }

    addModifierFlags(modifierFlags, &keyEvent)
    modifierFlags = []
    return true
  }

  public func isModeSwitchingKey(_ event: KeyEventData) -> Bool {
    let keyCode = Int(event.keyCode)
    return keyCode == kVK_JIS_Eisu || keyCode == kVK_JIS_Kana
  }

  /// Converts `event` into a Mozc key event. Returns nil when the event should not be sent (modifier changes
  /// that are not completed yet, unsupported keys, command-key shortcuts).
  public func getGenmaiKeyEvent(_ event: KeyEventData) -> KeyEvent? {
    var keyEvent = KeyEvent()
    return getGenmaiKeyCodeFromKeyEvent(event, &keyEvent) ? keyEvent : nil
  }

  public func getGenmaiKeyCodeFromKeyEvent(_ event: KeyEventData, _ keyEvent: inout KeyEvent) -> Bool {
    // This method uses |charactersIgnoringModifiers| basically but uses
    // |characters| if its modifier is only Shift.
    // For example:
    // \C-a   => CTRL + a  where characters = "\x01"
    // \S-a   => A         where characters = "\x41"
    // \C-S-a => CTRL + SHIFT + a where characters = "\x61"
    // \C-[   => Ctrl + [  where characters = "\x1b"
    // \S-[   => {         where characters = "\x7b"
    // \C-S-[ => CTRL + SHIFT + [ where characters = "\x5b"
    //
    // The main reason to do this is to avoid the confusion between \C-[
    // and ESC.
    if event.type == .flagsChanged {
      return handleModifierFlagsChange(event, &keyEvent)
    } else {
      modifierFlags = []
    }

    let inputString = Array(event.characters.utf16)
    let inputStringRaw = Array(event.charactersIgnoringModifiers.utf16)
    if inputString.isEmpty {
      return false
    }

    // strip caps lock effects.
    let nsModifiers = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
      .subtracting(.capsLock)
    let keyCode = event.keyCode
    let source = nsModifiers == .shift ? inputString : inputStringRaw
    guard let inputChar = source.first else {
      return false
    }
    if let special = kSpecialKeyMap[keyCode] {
      keyEvent.specialKey = special
    } else {
      if let special = kSpecialCharMap[inputChar] {
        keyEvent.specialKey = special
      } else if isGraph(inputChar) {
        keyEvent.keyCode = UInt32(inputChar)
      } else if inputChar == kYenMark {
        keyEvent.keyCode = UInt32(UInt8(ascii: "\\"))
      }

      // fill kana "key_string" if mode is kana.
      if inputMode == .kana && !keyEvent.hasSpecialKey {
        if nsModifiers == .shift, let kana = kKanaMapShift[keyCode] {
          keyEvent.keyString = kana
        } else if let kana = kKanaMap[keyCode] {
          keyEvent.keyString = kana
        }
      }
    }

    if nsModifiers.contains(.command) {
      // When command key is pressed, it is not a mozc key command.
      // Just ignore.
      return false
    }

    if nsModifiers == .shift && !keyEvent.hasSpecialKey {
      // If only the modifier is Shift and |keyEvent| is not normal key,
      // don't put any modifiers.
      return true
    }
    addModifierFlags(nsModifiers, &keyEvent)
    return true
  }
}

/// isgraph() in the "C" locale.
func isGraph(_ c: unichar) -> Bool { c > 0x20 && c < 0x7F }

/// isprint() in the "C" locale.
func isPrint(_ c: UInt32) -> Bool { c >= 0x20 && c < 0x7F }
